import test from 'node:test';
import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { readFileSync } from 'node:fs';
import { NoteStore } from '../src/note-store.ts';
import { searchNotes } from '../src/search.ts';
import { createServer } from '../src/http/server.ts';

async function withServer(fn: (base: string, store: NoteStore) => Promise<void>) {
  const store = new NoteStore();
  const server = createServer(store, () => {});
  await new Promise<void>((r) => server.listen(0, r));
  const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  try {
    await fn(base, store);
  } finally {
    server.closeAllConnections();
    await new Promise((r) => server.close(r));
  }
}

const post = (base: string, body: string) =>
  fetch(`${base}/notes`, { method: 'POST', headers: { 'content-type': 'application/json' }, body });

test('AC-1 POST /notes creates a note', async () => {
  await withServer(async (base, store) => {
    const res = await post(base, JSON.stringify({ title: 'a', body: 'b' }));
    assert.equal(res.status, 201);
    const note = await res.json();
    assert.equal(typeof note.id, 'number');
    assert.deepEqual(note, { id: note.id, title: 'a', body: 'b' });
    assert.deepEqual(store.list(), [note]);
