import { searchNotes } from '../search.ts';
import { type Result, ok, err } from '../result.ts';

export interface RouteRequest {
  method: string;
  pathname: string;
  query: URLSearchParams;
  body: () => Promise<Result<unknown>>;
}
export interface Reply { status: number; value: unknown }
type Params = string[];
type Handler = (store: NoteStore, req: RouteRequest, params: Params) => Promise<Result<Reply>> | Result<Reply>;
interface Route { method: string; pattern: RegExp; handler: Handler }

const reply = (r: Result<unknown>, status = 200): Result<Reply> =>
  r.ok ? ok({ status, value: r.value }) : r;

function parseNewNote(raw: unknown): Result<{ title: string; body: string }> {
  if (typeof raw !== 'object' || raw === null) return err('invalid body');
  const { title, body } = raw as Record<string, unknown>;
  if (typeof title !== 'string' || typeof body !== 'string') return err('invalid body');
  return ok({ title, body });
}

async function createNote(store: NoteStore, req: RouteRequest): Promise<Result<Reply>> {
  const raw = await req.body();
  if (!raw.ok) return raw;
  const parsed = parseNewNote(raw.value);
  if (!parsed.ok) return parsed;
  return reply(store.add(parsed.value.title, parsed.value.body), 201);
}

function getNote(store: NoteStore, _req: RouteRequest, params: Params): Result<Reply> {
  return reply(store.get(Number(params[0])));
}

function search(store: NoteStore, req: RouteRequest): Result<Reply> {
  return reply(searchNotes(store.list(), req.query.get('q') ?? ''));
}

const ROUTES: Route[] = [
  { method: 'GET', pattern: /^\/health$/, handler: () => ok({ status: 200, value: { status: 'ok' } }) },
  { method: 'POST', pattern: /^\/notes$/, handler: createNote },
  { method: 'GET', pattern: /^\/notes$/, handler: (s) => ok({ status: 200, value: s.list() satisfies Note[] }) },
  { method: 'GET', pattern: /^\/notes\/([1-9][0-9]*)$/, handler: getNote },
  { method: 'GET', pattern: /^\/search$/, handler: search },
];

export async function route(store: NoteStore, req: RouteRequest): Promise<Result<Reply>> {
  for (const r of ROUTES) {
    const m = r.method === req.method ? r.pattern.exec(req.pathname) : null;
    if (m) return r.handler(store, req, m.slice(1));
  }
  return err('not found');
