import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { NoteStore } from '../src/note-store.ts';
import { createServer } from '../src/http/server.ts';

async function withServer(fn: (base: string, store: NoteStore, lines: string[]) => Promise<void>) {
  const store = new NoteStore();
  const lines: string[] = [];
  const server = createServer(store, (l) => lines.push(l));
  await new Promise<void>((r) => server.listen(0, r));
  const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  try {
    await fn(base, store, lines);
  } finally {
    server.closeAllConnections();
    await new Promise((r) => server.close(r));
  }
}

const settle = () => new Promise((r) => setTimeout(r, 50));
const postNote = (base: string, title: string, body: string) =>
  fetch(`${base}/notes`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title, body }) });

test('AC-12 exactly one log line per request with method, path sans query, status, ms', async () => {
  await withServer(async (base, _s, lines) => {
    await (await fetch(`${base}/search?q=secretquery`)).text();
    await settle();
    assert.equal(lines.length, 1);
    assert.match(lines[0], /GET/);
    assert.match(lines[0], /\/search/);
    assert.ok(!lines[0].includes('secretquery') && !lines[0].includes('?'));
    assert.match(lines[0], /200/);
    assert.match(lines[0], /\d+ms/);
    await (await fetch(`${base}/nope`)).text();
    await (await postNote(base, 't', 'b')).text();
    await settle();
    assert.equal(lines.length, 3);
    assert.match(lines[1], /404/);
    assert.match(lines[2], /POST \/notes 201/);
  });
});

test('AC-13 no log line contains the request body', async () => {
  await withServer(async (base, _s, lines) => {
    const marker = `MARKER-${Date.now()}-zq9x`;
    const res = await postNote(base, 'title', marker);
    assert.equal(res.status, 201);
    await res.text();
    await settle();
    assert.ok(lines.length >= 1);
    assert.equal(lines.filter((l) => l.includes(marker)).length, 0);
  });
});

function p95(samples: number[]): number {
  const s = [...samples].sort((a, b) => a - b);
  return s[Math.ceil(s.length * 0.95) - 1];
}

async function measure(fn: () => Promise<Response>, n = 40): Promise<number> {
  const times: number[] = [];
  for (let i = 0; i < n; i++) {
    const t = performance.now();
    const res = await fn();
    await res.text();
    times.push(performance.now() - t);
  }
  return p95(times);
}

test('AC-14 p95 latency < 50ms for every endpoint with 1,000 notes', async () => {
  await withServer(async (base, store) => {
    for (let i = 0; i < 1000; i++) store.add(`note ${i}`, `body text ${i}`);
    const id = store.list()[500].id;
    const cases: Record<string, () => Promise<Response>> = {
      'POST /notes': () => postNote(base, 'perf', 'perf body'),
      'GET /notes': () => fetch(`${base}/notes`),
      'GET /notes/:id': () => fetch(`${base}/notes/${id}`),
      'GET /search': () => fetch(`${base}/search?q=note`),
      'GET /health': () => fetch(`${base}/health`),
    };
    for (const [name, fn] of Object.entries(cases)) {
      const v = await measure(fn);
      assert.ok(v < 50, `${name} p95 ${v.toFixed(1)}ms`);
    }
  });
});
