interface Reply { status: number; json: unknown }

async function call(method: string, path: string, body?: unknown): Promise<Reply> {
  const res = await fetch(base + path, {
    method,
    headers: body === undefined ? {} : { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  return { status: res.status, json: await res.json().catch(() => undefined) };
}

function expect(cond: boolean, detail: string): void {
  if (!cond) throw new Error(detail);
}

type Check = [name: string, run: () => Promise<void>];

async function main(): Promise<void> {
  const title = `smoke-${Date.now()}`;
  let id = 0;
  const checks: Check[] = [
    ['GET /health', async () => {
      const r = await call('GET', '/health');
      expect(r.status === 200, `expected 200, got ${r.status}`);
      expect(JSON.stringify(r.json) === '{"status":"ok"}', `unexpected body ${JSON.stringify(r.json)}`);
    }],
    ['POST /notes', async () => {
      const r = await call('POST', '/notes', { title, body: 'smoke test body' });
      expect(r.status === 201, `expected 201, got ${r.status}`);
      id = (r.json as { id: number }).id;
      expect(typeof id === 'number', 'response has no id');
    }],
    ['GET /notes/:id', async () => {
      const r = await call('GET', `/notes/${id}`);
      expect(r.status === 200, `expected 200, got ${r.status}`);
      const n = r.json as { id: number; title: string };
      expect(n.id === id && n.title === title, `unexpected note ${JSON.stringify(r.json)}`);
    }],
    ['GET /search', async () => {
      const r = await call('GET', `/search?q=${encodeURIComponent(title)}`);
      expect(r.status === 200, `expected 200, got ${r.status}`);
      expect(JSON.stringify(r.json).includes(title), 'created note not found in results');
    }],
  ];
  for (const [name, run] of checks) {
    try {
      await run();
      console.log(`PASS ${name}`);
    } catch (e) {
      console.error(`FAIL ${name}: ${e instanceof Error ? e.message : String(e)}`);
      process.exitCode = 1;
      return;
    }
  }
}

await main();
