import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { spawn } from 'node:child_process';
import { connect, type AddressInfo } from 'node:net';
import { NoteStore } from '../src/note-store.ts';
import { createServer } from '../src/http/server.ts';

const read = (p: string) => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8');

async function withServer(fn: (port: number, lines: string[]) => Promise<void>) {
  const lines: string[] = [];
  const server = createServer(new NoteStore(), (l) => lines.push(l));
  await new Promise<void>((r) => server.listen(0, r));
  try {
    await fn((server.address() as AddressInfo).port, lines);
  } finally {
    server.closeAllConnections();
    await new Promise((r) => server.close(r));
  }
}

test('AC-10 oversized request body is rejected with 413 and server stays up', async () => {
  await withServer(async (port) => {
    const big = JSON.stringify({ title: 't', body: 'x'.repeat(2 * 1024 * 1024) });
    const res = await fetch(`http://127.0.0.1:${port}/notes`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: big });
    assert.equal(res.status, 413);
    const ok = await fetch(`http://127.0.0.1:${port}/health`);
    assert.equal(ok.status, 200);
  });
});

test('AC-12 aborted request still writes exactly one log line', async () => {
  await withServer(async (port, lines) => {
    const sock = connect(port, '127.0.0.1');
    await new Promise<void>((r) => sock.on('connect', r));
    sock.write('POST /notes HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\nContent-Length: 100\r\n\r\n{"ti');
    await new Promise((r) => setTimeout(r, 50));
    sock.destroy();
    await new Promise((r) => setTimeout(r, 150));
    assert.equal(lines.length, 1, lines.join('\n'));
    assert.match(lines[0], /POST \/notes/);
  });
});

test('AC-22 smoke script does not call process.exit before output flushes', () => {
  assert.doesNotMatch(read('scripts/smoke.ts'), /process\.exit\(/);
});

test('AC-19 compose service is notes-api with a /health healthcheck', () => {
  const dc = read('docker-compose.yml');
  assert.match(dc, /^\s{2}notes-api:/m);
  assert.match(dc, /healthcheck:/);
  assert.match(dc, /\/health/);
});

test('AC-18 main exits 0 promptly on SIGTERM', async () => {
  const p = spawn('node', [new URL('../src/main.ts', import.meta.url).pathname], { env: { ...process.env, PORT: String(20000 + Math.floor(Math.random() * 20000)) } });
  await new Promise((r) => setTimeout(r, 800));
  const started = Date.now();
  const code = await new Promise<number | null>((resolve) => {
    p.on('exit', (c) => resolve(c));
    p.kill('SIGTERM');
  });
  assert.equal(code, 0);
  assert.ok(Date.now() - started < 3000);
});
