import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createServer as createHttp, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { NoteStore } from '../src/note-store.ts';
import { createServer } from '../src/http/server.ts';

const script = new URL('../scripts/smoke.ts', import.meta.url).pathname;

const listen = (s: Server) => new Promise<number>((r) => s.listen(0, () => r((s.address() as AddressInfo).port)));
const close = (s: Server) => new Promise<void>((r) => s.close(() => r()));
const runSmoke = (env: Record<string, string>) =>
  new Promise<{ status: number | null; out: string }>((resolve) => {
    import('node:child_process').then(({ spawn }) => {
      const p = spawn('node', [script], { env: { ...process.env, ...env } });
      let out = '';
      p.stdout.on('data', (d) => (out += d));
      p.stderr.on('data', (d) => (out += d));
      p.on('close', (status) => resolve({ status, out }));
    });
  });

test('AC-20 package.json has smoke script running scripts/smoke.ts', () => {
  const pkg = JSON.parse(readFileSync(new URL('../package.json', import.meta.url), 'utf8'));
  assert.match(pkg.scripts.smoke, /scripts\/smoke\.ts/);
});

test('AC-20 smoke script defaults to http://localhost:8081', () => {
  assert.match(readFileSync(script, 'utf8'), /http:\/\/localhost:8081/);
  assert.match(readFileSync(script, 'utf8'), /SMOKE_BASE_URL/);
});

test('AC-21 smoke exits 0 against a healthy service', async () => {
  const server = createServer(new NoteStore());
  const port = await listen(server);
  try {
    const r = await runSmoke({ SMOKE_BASE_URL: `http://localhost:${port}` });
    assert.equal(r.status, 0, r.out);
  } finally { await close(server); }
});

test('AC-22 smoke exits non-zero when service unreachable', async () => {
  const s = createHttp();
  const port = await listen(s);
  await close(s);
  const r = await runSmoke({ SMOKE_BASE_URL: `http://localhost:${port}` });
  assert.notEqual(r.status, 0);
  assert.match(r.out, /health/i);
});

test('AC-22 smoke exits non-zero and prints failing check on bad response', async () => {
  const s = createHttp((_req, res) => { res.writeHead(500); res.end('{}'); });
  const port = await listen(s);
  try {
    const r = await runSmoke({ SMOKE_BASE_URL: `http://localhost:${port}` });
    assert.notEqual(r.status, 0);
    assert.match(r.out, /FAIL.*health/i);
  } finally { await close(s); }
});
