{"type":"text","file":{"filePath":"/Users/cwijayasundaragmail.com/Documents/learning_101/run-brownfield4/src/http/body.ts","content":"import type { IncomingMessage } from 'node:http';
import { type Result, ok, err } from '../result.ts';

export function parseJson(text: string): Result<unknown> {
  try {
    return ok(JSON.parse(text) as unknown);
  } catch {
    return err('invalid json');
  }
}

export const MAX_BODY_BYTES = 1024 * 1024;

export async function readJsonBody(req: IncomingMessage): Promise<Result<unknown>> {
  try {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    // Never break out early: that would destroy the request and its socket,
    // so the 413 could not be delivered. Keep draining, discard the excess.
    for await (const chunk of req) {
      size += (chunk as Buffer).length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
      } else if (!tooLarge) {
        chunks.push(chunk as Buffer);
      }
    }
    if (tooLarge) return err('payload too large');
    return parseJson(Buffer.concat(chunks).toString('utf8'));
  } catch {
    return err('invalid json');
  }
}
