{"type":"text","file":{"filePath":"/Users/cwijayasundaragmail.com/Documents/learning_101/run-brownfield4/src/http/server.ts","content":"import { createServer as createHttpServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import type { NoteStore } from '../note-store.ts';
import { type Result, err } from '../result.ts';
import { readJsonBody } from './body.ts';
import { logRequest, stdoutSink, type LogSink } from './access-log.ts';
import { route, type Reply } from './router.ts';
import { statusForError } from './status.ts';

function toReply(result: Result<Reply>): Reply {
  if (result.ok) return result.value;
  return { status: statusForError(result.error), value: { error: result.error } };
}

function send(res: ServerResponse, reply: Reply): void {
  const payload = JSON.stringify(reply.value);
  res.writeHead(reply.status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) });
  res.end(payload);
}

async function dispatch(store: NoteStore, req: IncomingMessage, url: URL): Promise<Reply> {
  try {
    const result = await route(store, {
      method: req.method ?? 'GET',
      pathname: url.pathname,
      query: url.searchParams,
      body: () => readJsonBody(req),
    });
    return toReply(result);
  } catch {
    return toReply(err('internal error'));
  }
}

function parseUrl(req: IncomingMessage): URL | null {
  try {
    return new URL(req.url ?? '/', 'http://localhost');
  } catch {
    return null;
  }
}

export function createServer(store: NoteStore, log: LogSink = stdoutSink): Server {
  return createHttpServer((req, res) => {
    const start = performance.now();
    const url = parseUrl(req);
    res.on('close', () => {
      logRequest(log, req.method ?? '-', url?.pathname ?? '-', res.statusCode, performance.now() - start);
    });
    const done = url ? dispatch(store, req, url) : Promise.resolve(toReply(err('not found')));
    done
      .then((reply) => send(res, reply))
      .catch(() => {
        if (res.headersSent) res.destroy();
        else send(res, toReply(err('internal error')));
      });
  });
}
